1	/**
2	 * #{#rsz1a} #{#rsz1b} - Receipt Image Resizing
3	 *
4	 * Turns the **Source File** a person picked into the **Receipt Image** we store:
5	 * at most 2400px on the longest axis, JPEG at 85%, whatever arrived. The size
6	 * limits in `ReceiptService` describe the result of this function, not its
7	 * input — see `docs/adr/0006-the-stored-image-is-the-contract.md`.
8	 */
9	
10	export interface ResizeDimensions {
11		width: number;
12		height: number;
13	}
14	
15	/** Longest-axis budget for a stored Receipt Image. Chosen for human zoom, not OCR. */
16	export const MAX_IMAGE_DIMENSION = 2400;
17	
18	/** JPEG quality for a stored Receipt Image. */
19	export const IMAGE_QUALITY = 0.85;
20	
21	/** Every stored Receipt Image is a JPEG; only PDFs pass through untouched. */
22	const OUTPUT_TYPE = 'image/jpeg';
23	
24	/** The image types the receipts upload control offers. */
25	const RESIZABLE_TYPES = ['image/jpeg', 'image/png', 'image/heic'];
26	
27	/**
28	 * Whether a Source File of this type should be decoded and re-encoded.
29	 *
30	 * HEIC is included deliberately: Safari — the only place HEIC originates — can
31	 * decode it into a Canvas, and skipping it sent full-resolution phone photos
32	 * straight to storage. Anything else (PDFs, and image types we never offer) is
33	 * stored exactly as received.
34	 */
35	export function isResizableImage(mimeType: string): boolean {
36		return RESIZABLE_TYPES.includes(mimeType);
37	}
38	
39	/**
40	 * Rename a Source File to match the JPEG we actually store, so the storage
41	 * object's extension is not a lie. This never affects `original_filename`
42	 * (#{#ofn2a}), which keeps the name the person recognizes.
43	 */
44	export function toJpegFilename(filename: string): string {
45		return filename.replace(/(\.[^./\\]*)?$/, '.jpg');
46	}
47	
48	/**
49	 * #{#rsz1a} - Calculate resize dimensions maintaining aspect ratio
50	 *
51	 * Acceptance Criteria:
52	 * - Maximum dimension on longest axis must be MAX_IMAGE_DIMENSION
53	 * - Aspect ratio must be preserved during resize
54	 * - Images already within the budget keep original dimensions
55	 *
56	 * @param originalWidth - Original image width in pixels
57	 * @param originalHeight - Original image height in pixels
58	 * @param maxSize - Maximum dimension on longest axis
59	 * @returns New dimensions with preserved aspect ratio
60	 */
61	export function calculateResizeDimensions(
62		originalWidth: number,
63		originalHeight: number,
64		maxSize: number = MAX_IMAGE_DIMENSION
65	): ResizeDimensions {
66		const longestAxis = Math.max(originalWidth, originalHeight);
67	
68		// If image is already smaller than max, keep original dimensions
69		if (longestAxis <= maxSize) {
70			return { width: originalWidth, height: originalHeight };
71		}
72	
73		// Calculate scale factor
74		const scale = maxSize / longestAxis;
75	
76		// Calculate new dimensions (preserve aspect ratio)
77		return {
78			width: Math.round(originalWidth * scale),
79			height: Math.round(originalHeight * scale)
80		};
81	}
82	
83	/** Promise-shaped `canvas.toBlob`, which is callback-only. */
84	function encodeCanvas(canvas: HTMLCanvasElement, quality: number): Promise<Blob> {
85		return new Promise((resolve, reject) => {
86			canvas.toBlob(
87				(blob) => (blob ? resolve(blob) : reject(new Error('Failed to encode image'))),
88				OUTPUT_TYPE,
89				quality
90			);
91		});
92	}
93	
94	/**
95	 * #{#rsz1a} #{#rsz1b} - Resize an image file using Canvas API
96	 *
97	 * Acceptance Criteria:
98	 * - JPEG, PNG and HEIC are all resized, and all come out as JPEG. PNG could not
99	 *   honour a quality setting while it stayed PNG — `toBlob` ignores the argument
100	 *   for lossless formats — so a PNG "resize" used to be able to grow the file.
101	 * - Resizing occurs client-side (browser) before upload
102	 * - Images already within the budget are still re-encoded, and so still shrink
103	 * - EXIF orientation is honoured (#{#rsz2b})
104	 * - The file is decoded ONCE. `createImageBitmap` is itself the decode; the
105	 *   `<img>` element this used to load first was a second full decode of the same
106	 *   bytes, doubling peak memory on exactly the large photos we now accept.
107	 *
108	 * Throws if the image cannot be decoded or encoded — the caller decides whether
109	 * that is fatal.
110	 *
111	 * @param file - Source File
112	 * @param maxSize - Maximum dimension on longest axis
113	 * @param quality - Compression quality 0-1
114	 * @returns The Receipt Image to store
115	 */
116	export async function resizeImage(
117		file: File,
118		maxSize: number = MAX_IMAGE_DIMENSION,
119		quality: number = IMAGE_QUALITY
120	): Promise<File> {
121		if (!isResizableImage(file.type)) {
122			return file;
123		}
124	
125		// #{#rsz2b} - createImageBitmap applies EXIF orientation as it decodes
126		const bitmap = await createImageBitmap(file, { imageOrientation: 'from-image' });
127	
128		try {
129			const { width, height } = calculateResizeDimensions(bitmap.width, bitmap.height, maxSize);
130	
131			const canvas = document.createElement('canvas');
132			canvas.width = width;
133			canvas.height = height;
134	
135			const ctx = canvas.getContext('2d');
136			if (!ctx) throw new Error('Canvas context not available');
137			ctx.drawImage(bitmap, 0, 0, width, height);
138	
139			const blob = await encodeCanvas(canvas, quality);
140	
141			return new File([blob], toJpegFilename(file.name), {
142				type: OUTPUT_TYPE,
143				lastModified: file.lastModified
144			});
145		} finally {
146			bitmap.close();
147		}
148	}
