1	<script lang="ts">
2		/**
3		 * Receipt Image Viewer Component
4		 *
5		 * Provides zoom and pan capabilities for receipt images in a floating modal.
6		 * Implements specifications #{#zom1a} through #{#zom5b} from
7		 * specs/specifications/receipt-image-zoom-pan.md
8		 *
9		 * Zoom anchors to cursor position (mouse wheel, pinch midpoint, double-tap).
10		 * Scrollable container replaces manual pan — native scrollbars + drag-to-scroll.
11		 *
12		 * @component
13		 */
14	
15		import {
16			MIN_ZOOM,
17			ZOOM_STEP,
18			calculateFitDimensions,
19			calculateMaxZoom
20		} from '$lib/utils/imageZoom';
21	
22		// Props — #{#pdf1a} added isPdf for PDF detection
23		interface Props {
24			imageUrl: string;
25			altText?: string;
26			show?: boolean;
27			isPdf?: boolean;
28			onclose?: () => void;
29		}
30	
31		let {
32			imageUrl,
33			altText = 'Receipt image',
34			show = false,
35			isPdf = false,
36			onclose
37		}: Props = $props();
38	
39		// Zoom state - #{#zom1a}
40		let zoom = $state(100);
41	
42		// Drag-to-scroll state - #{#zom2a}
43		let isDragging = $state(false);
44		let dragStartX = $state(0);
45		let dragStartY = $state(0);
46		let scrollStartX = $state(0);
47		let scrollStartY = $state(0);
48	
49		// Touch gesture state - #{#zom3a}
50		let touchStartDistance = $state(0);
51		let touchStartZoom = $state(100);
52		let lastTapTime = $state(0);
53	
54		// Image base dimensions (fit-to-viewport at 100%)
55		let baseWidth = $state(0);
56		let baseHeight = $state(0);
57	
58		// The image's own resolution, which sets how far it can honestly be zoomed
59		let naturalWidth = $state(0);
60	
61		// Refs
62		let scrollContainer: HTMLDivElement | undefined = $state(undefined);
63	
64		// Constants
65		const PAN_STEP = 50;
66		const DOUBLE_TAP_DELAY = 300; // ms
67	
68		/**
69		 * The zoom ceiling is a property of THIS image, not a fixed percentage: it is
70		 * the point where one image pixel fills one CSS pixel. Beyond it the browser
71		 * would only interpolate, so the controls stop there — and for an image
72		 * already at or under viewport size they never leave 100% at all.
73		 */
74		let maxZoom = $derived(calculateMaxZoom(naturalWidth, baseWidth));
75	
76		// Pending scroll adjustment for zoom-to-cursor
77		let rafId = 0;
78	
79		// Computed scaled dimensions
80		let scaledWidth = $derived((baseWidth * zoom) / 100);
81		let scaledHeight = $derived((baseHeight * zoom) / 100);
82	
83		/**
84		 * Capture base dimensions on image load — the size the image
85		 * occupies at 100% zoom, fit within the viewport constraints.
86		 */
87		function handleImageLoad(e: Event) {
88			const img = e.target as HTMLImageElement;
89			naturalWidth = img.naturalWidth;
90			const fit = calculateFitDimensions(
91				img.naturalWidth,
92				img.naturalHeight,
93				window.innerWidth * 0.9,
94				window.innerHeight * 0.8
95			);
96			baseWidth = fit.width;
97			baseHeight = fit.height;
98		}
99	
100		/**
101		 * #{#zom1a} Zoom to a specific level, optionally anchored at a cursor position.
102		 * The point under the cursor stays fixed on screen after zoom.
103		 */
104		function zoomTo(newZoom: number, cursorX?: number, cursorY?: number) {
105			const container = scrollContainer;
106			newZoom = Math.max(MIN_ZOOM, Math.min(maxZoom, newZoom));
107	
108			if (!container || baseWidth === 0) {
109				zoom = newZoom;
110				return;
111			}
112	
113			const oldZoom = zoom;
114			if (newZoom === oldZoom) return;
115	
116			const rect = container.getBoundingClientRect();
117			// Default to center of viewport if no cursor position given
118			const cx = cursorX !== undefined ? cursorX - rect.left : rect.width / 2;
119			const cy = cursorY !== undefined ? cursorY - rect.top : rect.height / 2;
120	
121			// Point in base-image coordinates under the cursor
122			const imageX = (container.scrollLeft + cx) / (oldZoom / 100);
123			const imageY = (container.scrollTop + cy) / (oldZoom / 100);
124	
125			zoom = newZoom;
126	
127			// After Svelte updates the DOM (image resizes), adjust scroll so the
128			// same image point remains under the cursor.
129			const targetScrollLeft = imageX * (newZoom / 100) - cx;
130			const targetScrollTop = imageY * (newZoom / 100) - cy;
131			cancelAnimationFrame(rafId);
132			rafId = requestAnimationFrame(() => {
133				if (container) {
134					container.scrollLeft = targetScrollLeft;
135					container.scrollTop = targetScrollTop;
136				}
137			});
138		}
139	
140		/**
141		 * #{#zom1a} Zoom in by one step (snaps to 50% increments)
142		 *
143		 * The ceiling is rarely a multiple of ZOOM_STEP, so the last step lands on the
144		 * ceiling itself rather than overshooting it or becoming unreachable.
145		 */
146		function zoomIn(cursorX?: number, cursorY?: number) {
147			zoomTo(Math.min(Math.ceil((zoom + 1) / ZOOM_STEP) * ZOOM_STEP, maxZoom), cursorX, cursorY);
148		}
149	
150		/**
151		 * #{#zom1a} Zoom out by one step (snaps to 50% increments)
152		 */
153		function zoomOut(cursorX?: number, cursorY?: number) {
154			zoomTo(Math.floor((zoom - 1) / ZOOM_STEP) * ZOOM_STEP, cursorX, cursorY);
155		}
156	
157		/**
158		 * #{#zom1a} Reset zoom to 100% and scroll to origin
159		 */
160		function resetZoom() {
161			zoom = MIN_ZOOM;
162			if (scrollContainer) {
163				scrollContainer.scrollLeft = 0;
164				scrollContainer.scrollTop = 0;
165			}
166		}
167	
168		/**
169		 * #{#zom1b} #{#pdf1c} Handle mouse wheel zoom — disabled for PDFs.
170		 * Zooms toward the cursor position.
171		 */
172		function handleWheel(e: WheelEvent) {
173			if (isPdf) return; // #{#pdf1c} Let browser PDF viewer handle scroll
174			e.preventDefault();
175			if (e.deltaY < 0) {
176				zoomIn(e.clientX, e.clientY);
177			} else {
178				zoomOut(e.clientX, e.clientY);
179			}
180		}
181	
182		/**
183		 * #{#zom2a} #{#pdf1c} Handle mouse down to start drag-scrolling — disabled for PDFs
184		 */
185		function handleMouseDown(e: MouseEvent) {
186			if (isPdf) return; // #{#pdf1c}
187			if (zoom > MIN_ZOOM) {
188				isDragging = true;
189				dragStartX = e.clientX;
190				dragStartY = e.clientY;
191				scrollStartX = scrollContainer?.scrollLeft ?? 0;
192				scrollStartY = scrollContainer?.scrollTop ?? 0;
193				e.preventDefault();
194			}
195		}
196	
197		/**
198		 * #{#zom2a} Handle mouse move for drag-scrolling
199		 */
200		function handleMouseMove(e: MouseEvent) {
201			if (isDragging && scrollContainer) {
202				scrollContainer.scrollLeft = scrollStartX - (e.clientX - dragStartX);
203				scrollContainer.scrollTop = scrollStartY - (e.clientY - dragStartY);
204			}
205		}
206	
207		/**
208		 * #{#zom2a} Handle mouse up to stop drag-scrolling
209		 */
210		function handleMouseUp() {
211			isDragging = false;
212		}
213	
214		/**
215		 * #{#zom2b} #{#zom5a} #{#pdf1c} Handle keyboard navigation — zoom/pan disabled for PDFs
216		 */
217		function handleKeydown(e: KeyboardEvent) {
218			// Only handle keyboard shortcuts when the image viewer is open
219			if (!show) return;
220	
221			// Escape key closes modal - #{#zom5a} — works for both images and PDFs
222			if (e.key === 'Escape') {
223				close();
224				return;
225			}
226	
227			// #{#pdf1c} Skip zoom/pan keyboard shortcuts for PDFs
228			if (isPdf) return;
229	
230			// Arrow keys for scrolling when zoomed - #{#zom2b}
231			if (zoom > MIN_ZOOM && scrollContainer) {
232				switch (e.key) {
233					case 'ArrowUp':
234						scrollContainer.scrollTop -= PAN_STEP;
235						e.preventDefault();
236						break;
237					case 'ArrowDown':
238						scrollContainer.scrollTop += PAN_STEP;
239						e.preventDefault();
240						break;
241					case 'ArrowLeft':
242						scrollContainer.scrollLeft -= PAN_STEP;
243						e.preventDefault();
244						break;
245					case 'ArrowRight':
246						scrollContainer.scrollLeft += PAN_STEP;
247						e.preventDefault();
248						break;
249				}
250			}
251	
252			// Optional keyboard shortcuts for zoom - #{#zom2b}
253			if (e.key === '+' || e.key === '=') {
254				zoomIn();
255				e.preventDefault();
256			} else if (e.key === '-') {
257				zoomOut();
258				e.preventDefault();
259			} else if (e.key === '0') {
260				resetZoom();
261				e.preventDefault();
262			}
263		}
264	
265		/**
266		 * #{#zom3a} Calculate distance between two touch points
267		 */
268		function getTouchDistance(e: TouchEvent): number {
269			if (e.touches.length < 2) return 0;
270			const touch1 = e.touches[0];
271			const touch2 = e.touches[1];
272			const dx = touch1.clientX - touch2.clientX;
273			const dy = touch1.clientY - touch2.clientY;
274			return Math.sqrt(dx * dx + dy * dy);
275		}
276	
277		/**
278		 * #{#zom3a} Get midpoint between two touch points
279		 */
280		function getTouchMidpoint(e: TouchEvent): { x: number; y: number } {
281			return {
282				x: (e.touches[0].clientX + e.touches[1].clientX) / 2,
283				y: (e.touches[0].clientY + e.touches[1].clientY) / 2
284			};
285		}
286	
287		/**
288		 * #{#zom3a} #{#pdf1c} Handle touch start for pinch zoom and pan — disabled for PDFs
289		 */
290		function handleTouchStart(e: TouchEvent) {
291			if (isPdf) return; // #{#pdf1c}
292			if (e.touches.length === 2) {
293				// Pinch zoom start
294				touchStartDistance = getTouchDistance(e);
295				touchStartZoom = zoom;
296				e.preventDefault();
297			} else if (e.touches.length === 1) {
298				// Check for double tap - #{#zom3a}
299				const now = Date.now();
300				if (now - lastTapTime < DOUBLE_TAP_DELAY) {
301					// Double tap detected — zoom toward tap point
302					if (zoom === MIN_ZOOM) {
303						zoomTo(200, e.touches[0].clientX, e.touches[0].clientY);
304					} else {
305						resetZoom();
306					}
307					e.preventDefault();
308				}
309				lastTapTime = now;
310	
311				// Single touch drag-scroll (if zoomed)
312				if (zoom > MIN_ZOOM) {
313					isDragging = true;
314					dragStartX = e.touches[0].clientX;
315					dragStartY = e.touches[0].clientY;
316					scrollStartX = scrollContainer?.scrollLeft ?? 0;
317					scrollStartY = scrollContainer?.scrollTop ?? 0;
318				}
319			}
320		}
321	
322		/**
323		 * #{#zom3a} #{#pdf1c} Handle touch move for pinch zoom and pan — disabled for PDFs
324		 */
325		function handleTouchMove(e: TouchEvent) {
326			if (isPdf) return; // #{#pdf1c}
327			if (e.touches.length === 2) {
328				// Pinch zoom — anchored at midpoint between fingers
329				const currentDistance = getTouchDistance(e);
330				const mid = getTouchMidpoint(e);
331				const newZoom = touchStartZoom * (currentDistance / touchStartDistance);
332				zoomTo(newZoom, mid.x, mid.y);
333				e.preventDefault();
334			} else if (e.touches.length === 1 && isDragging && scrollContainer) {
335				// Drag to scroll
336				scrollContainer.scrollLeft = scrollStartX - (e.touches[0].clientX - dragStartX);
337				scrollContainer.scrollTop = scrollStartY - (e.touches[0].clientY - dragStartY);
338				e.preventDefault();
339			}
340		}
341	
342		/**
343		 * #{#zom3a} Handle touch end
344		 */
345		function handleTouchEnd() {
346			isDragging = false;
347			touchStartDistance = 0;
348		}
349	
350		/**
351		 * #{#zom2a} #{#zom3a} Wire the pointer/wheel/touch gestures imperatively.
352		 *
353		 * These are mouse/touch *enhancements* on a natively-scrollable container, with
354		 * full keyboard parity provided elsewhere (global arrow/zoom/Escape shortcuts on
355		 * <svelte:window> and the Tab-reachable zoom buttons). There is no ARIA role that
356		 * accurately models a custom zoom/pan surface, so attaching the listeners via an
357		 * action (rather than markup `on*` handlers) keeps the element honestly
358		 * role-less. wheel/touchstart/touchmove are registered non-passive because the
359		 * handlers call preventDefault().
360		 */
361		function gestureSurface(node: HTMLElement) {
362			const active = { passive: false } as AddEventListenerOptions;
363			node.addEventListener('wheel', handleWheel, active);
364			node.addEventListener('mousedown', handleMouseDown);
365			node.addEventListener('touchstart', handleTouchStart, active);
366			node.addEventListener('touchmove', handleTouchMove, active);
367			node.addEventListener('touchend', handleTouchEnd);
368			return {
369				destroy() {
370					node.removeEventListener('wheel', handleWheel);
371					node.removeEventListener('mousedown', handleMouseDown);
372					node.removeEventListener('touchstart', handleTouchStart);
373					node.removeEventListener('touchmove', handleTouchMove);
374					node.removeEventListener('touchend', handleTouchEnd);
375				}
376			};
377		}
378	
379		/**
380		 * #{#rim1b} Close the viewer
381		 */
382		function close() {
383			onclose?.();
384			resetZoom(); // #{#zom4a} Reset state when closing
385		}
386	
387		/**
388		 * #{#rim1b} Handle backdrop click
389		 */
390		function handleBackdropClick(e: MouseEvent) {
391			if (e.target === e.currentTarget) {
392				close();
393			}
394		}
395	
396		/**
397		 * #{#rim1b} Keyboard equivalent of the backdrop click: Escape dismisses the modal.
398		 * (Escape is also handled globally via <svelte:window>; this keeps the dialog
399		 * element's click action paired with a keyboard action for accessibility.)
400		 */
401		function handleBackdropKeydown(e: KeyboardEvent) {
402			if (e.key === 'Escape') {
403				close();
404			}
405		}
406	
407		/**
408		 * #{#zom4a} Reset state when component shows
409		 */
410		$effect(() => {
411			if (show) {
412				resetZoom();
413				baseWidth = 0;
414				baseHeight = 0;
415				naturalWidth = 0;
416			}
417		});
418	
419		/**
420		 * #{#zom2a} Compute cursor style based on zoom and drag state
421		 */
422		let cursorStyle = $derived(zoom > MIN_ZOOM ? (isDragging ? 'grabbing' : 'grab') : 'default');
423	</script>
424	
425	<svelte:window onmousemove={handleMouseMove} onmouseup={handleMouseUp} onkeydown={handleKeydown} />
426	
427	{#if show}
428		<!-- #{#zom5a} Modal with proper ARIA attributes -->
429		<div
430			class="fixed inset-0 z-60 flex items-center justify-center bg-black/90 p-4"
431			onclick={handleBackdropClick}
432			onkeydown={handleBackdropKeydown}
433			role="dialog"
434			aria-modal="true"
435			aria-labelledby="receipt-image-viewer-title"
436			tabindex="-1"
437			style="touch-action: {isPdf ? 'auto' : 'none'};"
438		>
439			<!-- #{#zom5a} Screen reader title -->
440			<h2 id="receipt-image-viewer-title" class="sr-only">Receipt Image Viewer</h2>
441	
442			<!-- #{#rim1b} Close button -->
443			<button
444				onclick={close}
445				class="absolute top-4 right-4 text-white transition-colors hover:text-gray-300"
446				aria-label="Close image viewer"
447				type="button"
448			>
449				<svg class="h-8 w-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
450					<path
451						stroke-linecap="round"
452						stroke-linejoin="round"
453						stroke-width="2"
454						d="M6 18L18 6M6 6l12 12"
455					/>
456				</svg>
457			</button>
458	
459			<!-- #{#pdf1b} PDF display with white background -->
460			{#if isPdf}
461				<div
462					class="relative flex max-h-[80vh] max-w-[90vw] items-center justify-center"
463					role="document"
464					aria-label={altText}
465				>
466					<iframe src={imageUrl} title={altText} class="h-[80vh] w-[90vw] rounded bg-white"></iframe>
467				</div>
468			{:else}
469				<!--
470					Scrollable image container — replaces fixed-viewport + manual pan.
471					Gestures (wheel-zoom, drag-pan, pinch) are wired via use:gestureSurface so
472					the element stays role-less; the receipt is exposed to assistive tech
473					through the inner <img alt>, and keyboard control lives on the window
474					shortcuts and the zoom buttons.
475				-->
476				<div
477					bind:this={scrollContainer}
478					class="receipt-scroll-container relative overflow-auto rounded"
479					use:gestureSurface
480					style={baseWidth > 0
481						? `width: ${Math.min(scaledWidth, window.innerWidth * 0.9)}px; height: ${baseHeight}px; max-width: 90vw; max-height: 80vh; cursor: ${cursorStyle};`
482						: `max-width: 90vw; max-height: 80vh; cursor: ${cursorStyle};`}
483				>
484					{#if baseWidth > 0}
485						<!-- #{#rim2a} Receipt image — sized directly for natural scroll -->
486						<img
487							src={imageUrl}
488							alt={altText}
489							class="block max-w-none select-none"
