/**
 * #{#rsz1a} #{#rsz1b} - Receipt Image Resizing
 *
 * Resizes images before upload to optimize for Mistral OCR processing.
 * - Max dimension: 2000px on longest axis
 * - Compression: 85% quality
 * - Supports: JPEG, PNG
 */

export interface ResizeDimensions {
	width: number;
	height: number;
}

/**
 * #{#rsz1a} - Calculate resize dimensions maintaining aspect ratio
 *
 * Acceptance Criteria:
 * - Maximum dimension on longest axis must be 2000px
 * - Aspect ratio must be preserved during resize
 * - Images smaller than 2000px on longest axis keep original dimensions
 *
 * @param originalWidth - Original image width in pixels
 * @param originalHeight - Original image height in pixels
 * @param maxSize - Maximum dimension on longest axis (default: 2000)
 * @returns New dimensions with preserved aspect ratio
 */
export function calculateResizeDimensions(
	originalWidth: number,
	originalHeight: number,
	maxSize: number = 2000
): ResizeDimensions {
	const longestAxis = Math.max(originalWidth, originalHeight);

	// If image is already smaller than max, keep original dimensions
	if (longestAxis <= maxSize) {
		return { width: originalWidth, height: originalHeight };
	}

	// Calculate scale factor
	const scale = maxSize / longestAxis;

	// Calculate new dimensions (preserve aspect ratio)
	return {
		width: Math.round(originalWidth * scale),
		height: Math.round(originalHeight * scale)
	};
}

/**
 * #{#rsz1a} #{#rsz1b} - Resize an image file using Canvas API
 *
 * Acceptance Criteria:
 * - Both JPEG and PNG formats must be resized
 * - Lossy compression at 85% quality must be applied
 * - Original filename extension must be preserved
 * - Resizing must occur client-side (browser) before upload
 * - Images smaller than 2000px still have compression applied
 * - EXIF orientation must be handled (#{#rsz2b})
 *
 * @param file - Original image file (JPEG or PNG)
 * @param maxSize - Maximum dimension on longest axis (default: 2000)
 * @param quality - Compression quality 0-1 (default: 0.85)
 * @returns Resized image file
 */
export async function resizeImage(
	file: File,
	maxSize: number = 2000,
	quality: number = 0.85
): Promise<File> {
	// Only resize JPEG and PNG
	if (!['image/jpeg', 'image/png'].includes(file.type)) {
		return file;
	}

	return new Promise((resolve, reject) => {
		const img = new Image();
		const canvas = document.createElement('canvas');
		const ctx = canvas.getContext('2d');

		if (!ctx) {
			reject(new Error('Canvas context not available'));
			return;
		}

		img.onload = async () => {
			try {
				// #{#rsz2b} - Handle EXIF orientation using createImageBitmap
				const bitmap = await createImageBitmap(file, {
					imageOrientation: 'from-image'
				});

				// Calculate new dimensions
				const { width, height } = calculateResizeDimensions(bitmap.width, bitmap.height, maxSize);

				// Set canvas size
				canvas.width = width;
				canvas.height = height;

				// Draw resized image
				ctx.drawImage(bitmap, 0, 0, width, height);

				// Convert to blob with compression
				canvas.toBlob(
					(blob) => {
						if (!blob) {
							reject(new Error('Failed to create blob'));
							return;
						}

						// #{#rsz3b} - Log resize metrics
						const originalSize = file.size;
						const resizedSize = blob.size;
						const reduction = ((1 - resizedSize / originalSize) * 100).toFixed(1);

						console.log('Image resized:', {
							originalSize: `${(originalSize / 1024).toFixed(2)}KB`,
							resizedSize: `${(resizedSize / 1024).toFixed(2)}KB`,
							reduction: `${reduction}%`,
							originalDimensions: `${bitmap.width}x${bitmap.height}`,
							resizedDimensions: `${width}x${height}`,
							format: file.type
						});

						// Create new File from blob
						const resizedFile = new File([blob], file.name, {
							type: file.type,
							lastModified: Date.now()
						});

						// Clean up
						URL.revokeObjectURL(img.src);
						bitmap.close();

						resolve(resizedFile);
					},
					file.type,
					quality
				);
			} catch (error) {
				URL.revokeObjectURL(img.src);
				reject(error);
			}
		};

		img.onerror = () => {
			URL.revokeObjectURL(img.src);
			reject(new Error('Failed to load image'));
		};

		// Load image
		img.src = URL.createObjectURL(file);
	});
}

